## Code Example
```javascript
function minPathWithOneRemoval(grid) {
  const m = grid.length, n = grid[0].length;
  const dp0 = Array(m).fill().map(() => Array(n).fill(Infinity));
  const dp1 = Array(m).fill().map(() => Array(n).fill(Infinity));

  dp0[0][0] = grid[0][0];
  dp1[0][0] = 0;

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i > 0) {
        dp0[i][j] = Math.min(dp0[i][j], grid[i][j] + dp0[i-1][j]);
        dp1[i][j] = Math.min(dp1[i][j], grid[i][j] + dp1[i-1][j]);
        dp1[i][j] = Math.min(dp1[i][j], dp0[i-1][j]);
      }
      if (j > 0) {
        dp0[i][j] = Math.min(dp0[i][j], grid[i][j] + dp0[i][j-1]);
        dp1[i][j] = Math.min(dp1[i][j], grid[i][j] + dp1[i][j-1]);
        dp1[i][j] = Math.min(dp1[i][j], dp0[i][j-1]);
      }
    }
  }

  return Math.min(dp0[m-1][n-1], dp1[m-1][n-1]);
}
```

## Time/Space Complexity
- Time: O(m × n) - we process each cell once
- Space: O(m × n) - can be optimized to O(n) using rolling arrays since we only need the previous row

## Why This Is Asked
Tests knowledge of a practical data structure for real-world features (auto-complete) and how to extend it with per-word frequencies.

## Key Concepts
- Trie with terminal frequency tracking
- DFS/BFS to collect candidate words from a prefix
- Sorting by frequency then lexicographic order
- Edge cases: missing prefix, zero matches, tie handling

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.freq = 0; // frequency for word ending here
  }
}
class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, new TrieNode());
      node = node.next.get(ch);
    }
    node.freq += 1;
  }
  autocomplete(prefix, K) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.next.has(ch)) return [];
      node = node.next.get(ch);
    }
    const results = [];
    const dfs = (n, path) => {
      if (n.freq > 0) results.push([path, n.freq]);
      for (const [ch, child] of n.next) dfs(child, path + ch);
    };
    dfs(node, prefix);
    results.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    return results.slice(0, K).map(v => v[0]);
  }
}
```

